#!/usr/bin/env bash
# Contract for tests/check_fork_ci_noise.sh: this is the only thing standing
# between a push and a mail to the fork owner per push, and it is the one branch
# gate with no self-test — a widened match or a lost fork gate would silent-pass
# the very workflow that can only fail on a fork.
#
# Trees are built with mktree/commit-tree in a throwaway repository, so no ref,
# remote or worktree of the host checkout is touched.
#
# Generated by omp (Qwen3.8-Flash-Next) without human creative authorship.
# SPDX-License-Identifier: LGPL-2.1-or-later

set -u

root=$(git rev-parse --show-toplevel 2>/dev/null) || {
    printf 'SKIP  fork-ci-noise self-test (not inside a git checkout)\n'
    exit 125
}
gate=$root/tests/check_fork_ci_noise.sh
if [ ! -f "$gate" ]; then
    printf 'fork-ci-noise self-test: gate missing at %s\n' "$gate" >&2
    exit 1
fi

# Not a bare /tmp: a native git.exe and this bash disagree about where that
# name lives (docs/agents/…Windows notes), so the sandbox is built under
# %USERPROFILE% like tests/check_pr_bodies_test.sh does.
if command -v cygpath >/dev/null 2>&1 && [ -n "${USERPROFILE:-}" ]; then
    tmpbase=$(cygpath -u "${USERPROFILE:-}")
else
    tmpbase=${TMPDIR:-/tmp}
fi
tmp=$(mktemp -d "$tmpbase/pime-fork-noise-selftest.XXXXXX")
repo=$tmp/repo
trap 'rm -rf "$tmp"' EXIT

export GIT_AUTHOR_NAME=selftest GIT_AUTHOR_EMAIL=selftest@example.invalid
export GIT_COMMITTER_NAME=selftest GIT_COMMITTER_EMAIL=selftest@example.invalid

failures=0

expect() { # <want> <name> <ref>
    local want=$1 name=$2 ref=$3 got
    ( cd "$repo" && bash "$gate" "$ref" >"$tmp/out" 2>&1 )
    got=$?
    if [ "$got" -ne "$want" ]; then
        printf 'FAIL  %s: want %s got %s\n' "$name" "$want" "$got"
        sed 's/^/      /' "$tmp/out"
        failures=$((failures + 1))
    else
        printf 'ok    %s (%s)\n' "$name" "$(head -n 1 "$tmp/out")"
    fi
}

git init -q "$repo" || { printf 'sandbox git init failed\n' >&2; exit 1; }

# A workflow file is three levels deep, and mktree builds one level at a time.
workflow_tree() { # <content> -> tree sha of .github/workflows
    local blob
    blob=$(printf '%s\n' "$1" | git -C "$repo" hash-object -w --stdin)
    printf '100644 blob %s\tci.yaml\n' "$blob" | git -C "$repo" mktree
}

commit_with_workflows() { # <workflows-tree> <message> -> commit sha
    local wf=$1 github
    github=$(printf '040000 tree %s\tworkflows\n' "$wf" | git -C "$repo" mktree)
    local top
    top=$(printf '040000 tree %s\t.github\n' "$github" | git -C "$repo" mktree)
    printf '%s\n' "$2" | git -C "$repo" commit-tree "$top"
}

unhardened="name: CI
on:
  push:
    branches: ['**']
jobs:
  build-and-sign:
    uses: ./.github/workflows/build-and-sign.yaml
"

hardened="name: CI
on:
  push:
    branches: ['master']
jobs:
  build-and-sign:
    if: github.repository == 'EasyIME/PIME'
    uses: ./.github/workflows/build-and-sign.yaml
"

signpath_ungated="name: CI
on:
  pull_request:
jobs:
  sign:
    uses: ./.github/workflows/build-and-sign.yaml
"

git -C "$repo" update-ref refs/heads/noise/wildcard \
    "$(commit_with_workflows "$(workflow_tree "$unhardened")" 'ci: unhardened trigger')"
expect 1 'push trigger for every branch fails' noise/wildcard

git -C "$repo" update-ref refs/heads/noise/hardened \
    "$(commit_with_workflows "$(workflow_tree "$hardened")" 'ci: hardened')"
expect 0 'master-only push with the fork gate is quiet' noise/hardened

git -C "$repo" update-ref refs/heads/noise/signpath \
    "$(commit_with_workflows "$(workflow_tree "$signpath_ungated")" 'ci: signs on the fork')"
expect 1 'SignPath call without a fork gate fails' noise/signpath

# The product-branch exemption: a ref whose .github/workflows tree is identical
# to the product master's keeps the upstream triggers, so the mails are inherent
# to pushing rather than a local mistake.
git -C "$repo" remote add product https://github.com/EasyIME/PIME.git
product_commit=$(commit_with_workflows "$(workflow_tree "$unhardened")" 'product master')
git -C "$repo" update-ref refs/remotes/product/master "$product_commit"
git -C "$repo" update-ref refs/heads/noise/product \
    "$(commit_with_workflows "$(workflow_tree "$unhardened")" 'pr: product change')"
expect 0 'product-identical workflows are exempt' noise/product

# A ref that is not a commit is not applicable, and a missing argument is usage.
expect 125 'non-commit ref skips' "$(printf 'x\n' | git -C "$repo" hash-object -w --stdin)"
( cd "$repo" && bash "$gate" >"$tmp/out" 2>&1 )
if [ $? -ne 2 ]; then
    printf 'FAIL  no argument: want 2 got %s\n' "$?"
    failures=$((failures + 1))
else
    printf 'ok    no argument is usage\n'
fi

printf '%d failed\n' "$failures"
[ "$failures" -eq 0 ]
